cd /tmp/vally-eval-trial-dAACKe && P=.copilot-tracking/skraft-plans/pricing && mkdir -p $P/features $P/details/2026-11-09 $P/evidence/2026-11-09/discount tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > $P/features/pricing-loyalty-discount.feature <<'E'
Feature: Loyalty discount at checkout
  A returning customer's loyalty tier is reflected in the checkout total.

  # SETTLED: AC-1..AC-4 (ac.md). Values are copied verbatim.
  # NOT DECIDED: Platinum tier. The business has not agreed a reduction, so no
  # scenario exists for it. See "Open questions" at the end of this file.

  @loyalty-discount @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price for a basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @loyalty-discount @happy-path
  Scenario: Silver customer is charged the Silver price for a basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @loyalty-discount @happy-path
  Scenario: Gold customer is charged the Gold price for a basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @loyalty-discount @edge-case
  Scenario: Bronze customer with a tiny basket is charged on a whole cent
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents

  # Open questions (no scenario, escalated to DISCUSS):
  #  - OQ-1 Platinum tier: reduction undecided; no expected value exists.
  #  - OQ-2 AC-4 title says the rounding is "in the customer's favour", yet the
  #    expected 7 cents means no reduction is applied (5% of 7 = 0.35 cents).
  #    Rounding the reduction down to 0 favours the shop, not the customer.
  #    The 7-cent value is kept verbatim; the business must confirm the rule.
E
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    // Bronze customer is charged the Bronze price for a basket (AC-1)
    [Theory]
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Customer_is_charged_the_price_of_their_loyalty_tier(
        LoyaltyTier tier, int subtotalCents, int expectedChargedCents)
    {
        var quote = new CalculateLoyaltyDiscount()
            .Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
E
ls $P/features tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount

